+  height:22px;
+  border-radius:6px;
+  background: linear-gradient(135deg, rgba(0,102,204,.9), rgba(0,0,0,.85));
+}
+.navlinks{display:flex; align-items:center; gap:18px; font-size:13px; color:var(--text)}
+.navlinks a{padding:8px 10px; border-radius:10px}
+.navlinks a:hover{background:rgba(0,0,0,.05)}
+.navlinks .cta{color:var(--accent)}
+.navlinks .cta:hover{background:rgba(0,102,204,.10)}
+
+/* Ribbon */
+.ribbon{
+  background:var(--bg-muted);
+  color:var(--text);
+  border-bottom:1px solid var(--border);
+}
+.ribbon__inner{padding:12px 0; font-size:13px; color:var(--text-muted); text-align:center}
+.ribbon__inner a{color:var(--accent)}
+.ribbon__inner a:hover{color:var(--accent-hover); text-decoration:underline}
+
+/* Typography */
+.eyebrow{font-size:13px; color:var(--text-muted); letter-spacing:.2px}
+h1,h2,h3{margin:0}
+h1{font-size:52px; line-height:1.06; letter-spacing:-.02em}
+h2{font-size:40px; line-height:1.08; letter-spacing:-.02em}
+h3{font-size:22px; line-height:1.14}
+p{margin:0; color:var(--text-muted)}
+.lead{font-size:19px; color:var(--text-muted)}
+
+/* Section rhythm */
+section{padding:60px 0}
