+  border-radius: var(--radius-lg);
+  background: rgba(255,255,255,.75);
+  border:1px solid var(--border);
+  box-shadow: 0 20px 60px rgba(0,0,0,.08);
+  padding:34px;
+}
+.hero__card p{margin-top:10px}
+.hero__cta{margin-top:18px; display:flex; flex-wrap:wrap; gap:10px}
+.hero__visual{
+  border-radius: var(--radius-lg);
+  background: linear-gradient(135deg, rgba(255,255,255,.85), rgba(245,245,247,1));
+  border:1px solid var(--border);
+  position:relative;
+  overflow:hidden;
+  min-height: 280px;
+}
+.hero__visual::before{
+  content:"";
+  position:absolute;
+  inset:-60px;
+  background: radial-gradient(circle at 30% 30%, rgba(0,102,204,.22), transparent 45%),
+    radial-gradient(circle at 70% 30%, rgba(255,140,0,.18), transparent 48%),
+    radial-gradient(circle at 55% 70%, rgba(0,0,0,.10), transparent 55%);
+  transform: rotate(-6deg);
+}
+.hero__visual::after{
+  content:"";
+  position:absolute;
+  left:18px;
+  right:18px;
+  bottom:18px;
+  height: 64px;
+  border-radius: 18px;
+  background: rgba(255,255,255,.65);
+  border:1px solid var(--border);
+}
+
+/* Carousels */
+.carousel{position:relative}
+.carousel__viewport{
+  display:grid;
+  grid-auto-flow:column;
+  grid-auto-columns: minmax(280px, 1fr);
+  gap:16px;
+  overflow:auto;
+  scroll-snap-type:x mandatory;
+  padding-bottom:6px;
+  overscroll-behavior-x:contain;
+  -webkit-overflow-scrolling:touch;
+}
+.carousel__viewport::-webkit-scrollbar{height:10px}
+.carousel__viewport::-webkit-scrollbar-thumb{background:rgba(0,0,0,.10); border-radius:999px}
+.carousel__viewport::-webkit-scrollbar-track{background:transparent}
+.carousel__item{scroll-snap-align:start}
+.carousel__nav{
+  position:absolute;
+  top: calc(50% - 22px);
+  width:44px;
+  height:44px;
+  border-radius:999px;
