+  box-shadow: 0 10px 25px rgba(0,0,0,.10);
+  display:flex;
+  align-items:center;
+  justify-content:center;
+  cursor:pointer;
+  transition: transform .12s ease, opacity .12s ease;
+}
+.carousel__nav:hover{transform: translateY(-1px)}
+.carousel__nav[disabled]{opacity:.35; cursor:default; transform:none}
+.carousel__nav--prev{left:-10px}
+.carousel__nav--next{right:-10px}
+.carousel__nav svg{width:18px; height:18px; fill:var(--text)}
+
+/* Cards */
+.card{
+  border-radius: var(--radius-lg);
+  border:1px solid var(--border);
+  background: var(--card);
+  box-shadow: 0 10px 30px rgba(0,0,0,.06);
+  overflow:hidden;
+  min-height: 320px;
+  display:flex;
+  flex-direction:column;
+}
+.card__media{
+  height:170px;
+  background: linear-gradient(135deg, rgba(0,102,204,.12), rgba(245,245,247,1));
+  position:relative;
+}
+.card__media--warm{background: linear-gradient(135deg, rgba(255,140,0,.18), rgba(245,245,247,1))}
+.card__media--cool{background: linear-gradient(135deg, rgba(105,90,205,.18), rgba(245,245,247,1))}
+.card__media--mint{background: linear-gradient(135deg, rgba(0,160,130,.16), rgba(245,245,247,1))}
+.card__media::after{
+  content:"";
+  position:absolute;
+  inset:14px;
+  border-radius: 18px;
+  border:1px dashed rgba(29,29,31,.18);
+  background: rgba(255,255,255,.55);
+}
+.card__body{padding:18px 18px 16px; display:flex; flex-direction:column; gap:10px; flex:1}
+.card__meta{display:flex; align-items:center; justify-content:space-between; gap:10px}
+.badge{
+  font-size:11px;
+  font-weight:600;
+  letter-spacing:.18em;
+  text-transform:uppercase;
+  color: rgba(0,102,204,1);
+  background: rgba(0,102,204,.10);
+  border:1px solid rgba(0,102,204,.18);
+  padding:6px 10px;
+  border-radius:999px;
+}
+.price{font-size:14px; color:var(--text); font-weight:600}
+.subprice{font-size:13px; color:var(--text-muted)}
+.card__title{display:flex; flex-direction:column; gap:4px}
+.card__title strong{font-size:18px}
+.card__actions{margin-top:auto; display:flex; gap:12px; align-items:center; flex-wrap:wrap}
+.card__actions a{color:var(--accent); font-size:14px}
+.card__actions a:hover{color:var(--accent-hover); text-decoration:underline}
+
+/* Product icon bar */
+.iconbar{
+  display:grid;
+  grid-auto-flow:column;
+  grid-auto-columns: minmax(140px, 1fr);
+  gap:12px;
+  overflow:auto;
+  padding: 12px 0;
+  scroll-snap-type:x mandatory;
+}
+.iconbar::-webkit-scrollbar{height:10px}
+.iconbar::-webkit-scrollbar-thumb{background:rgba(0,0,0,.10); border-radius:999px}
+.iconbar__item{
+  scroll-snap-align:start;
+  border-radius: 18px;
+  border:1px solid var(--border);
+  background: rgba(255,255,255,.75);
+  padding:14px;
+  display:flex;
+  align-items:center;
+  gap:12px;
+  min-height:64px;
+}
+.iconbar__thumb{
+  width:36px;
+  height:36px;
+  border-radius: 12px;
+  background: linear-gradient(135deg, rgba(0,0,0,.08), rgba(0,102,204,.16));
+  border:1px solid var(--border);
+}
+.iconbar__label{font-size:14px; font-weight:600}
+.iconbar__item:hover{background:#fff}
