+.grid{
+  display:grid;
+  grid-template-columns: repeat(12, 1fr);
+  gap:18px;
+}
+.tile{
+  border-radius: var(--radius-lg);
+  border:1px solid var(--border);
+  background: #fff;
+  overflow:hidden;
+  min-height: 380px;
+  position:relative;
+  box-shadow: 0 20px 60px rgba(0,0,0,.08);
+}
+.tile__inner{padding:26px; display:flex; flex-direction:column; height:100%}
+.tile__media{
+  margin-top:14px;
+  flex:1;
+  border-radius: 20px;
+  border:1px solid var(--border);
+  background: radial-gradient(circle at 35% 25%, rgba(0,102,204,.22), transparent 45%),
+    radial-gradient(circle at 65% 35%, rgba(255,140,0,.16), transparent 55%),
+    linear-gradient(135deg, rgba(245,245,247,1), rgba(255,255,255,1));
+  position:relative;
+  overflow:hidden;
+}
+.tile__media::after{
+  content:"";
+  position:absolute;
+  inset:16px;
+  border-radius: 18px;
+  background: rgba(255,255,255,.55);
+  border:1px dashed rgba(29,29,31,.20);
+}
+.tile__kicker{font-size:13px; color:var(--text-muted)}
+.tile__title{margin-top:6px; font-size:32px; letter-spacing:-.02em}
+.tile__copy{margin-top:8px; font-size:15px}
+.tile__actions{margin-top:14px; display:flex; gap:14px; flex-wrap:wrap}
+.tile__actions a{color:var(--accent); font-size:14px}
+.tile__actions a:hover{color:var(--accent-hover); text-decoration:underline}
+
+.tile--wide{grid-column: span 12}
+.tile--half{grid-column: span 6}
+.tile--third{grid-column: span 4}
+.tile--muted{background: linear-gradient(180deg, rgba(245,245,247,1), rgba(255,255,255,1))}
+
+/* Tabs */
+.tabs{display:flex; flex-wrap:wrap; gap:10px}
+.tab{
+  border:1px solid var(--border);
+  background: rgba(255,255,255,.70);
+  color:var(--text);
+  height: 40px;
+  padding:0 14px;
+  border-radius:999px;
+  cursor:pointer;
+  font-size:14px;
+}
+.tab[aria-selected="true"]{background: rgba(0,102,204,.10); border-color: rgba(0,102,204,.25); color: var(--accent)}
+.tab:hover{background:#fff}
+
+/* Sticky section nav */
+.sectionnav{
+  position:sticky;
+  top:54px;
+  z-index:40;
+  background: rgba(255,255,255,.88);
+  backdrop-filter: blur(16px) saturate(180%);
+  border-bottom: 1px solid var(--border);
+}
+.sectionnav__inner{display:flex; gap:12px; overflow:auto; padding:12px 0}
+.sectionnav__inner a{
+  white-space:nowrap;
+  font-size:13px;
+  color:var(--text);
+  border:1px solid transparent;
+  padding:8px 12px;
+  border-radius:999px;
+}
+.sectionnav__inner a:hover{background: rgba(0,0,0,.05)}
+.sectionnav__inner a.is-active{border-color: rgba(0,102,204,.22); background: rgba(0,102,204,.10); color:var(--accent)}
+
+/* Help blocks / quick links */
+.twocol{display:grid; grid-template-columns: repeat(12, 1fr); gap:18px}
+.panel{
+  grid-column: span 6;
+  border-radius: var(--radius-lg);
+  border:1px solid var(--border);
+  background: rgba(255,255,255,.75);
+  padding:22px;
+  box-shadow: 0 10px 30px rgba(0,0,0,.06);
+}
+.panel h3{margin-bottom:8px}
+.panel p{margin-bottom:14px}
+.quicklinks{display:flex; gap:10px; flex-wrap:wrap}
+
+/* Footer */
+.footer{background: var(--bg-muted); border-top:1px solid var(--border)}
+.footer__inner{padding:34px 0 26px}
+.footer__cols{display:grid; grid-template-columns: repeat(12, 1fr); gap:18px}
+.footer__col{grid-column: span 3}
+.footer__col h4{margin:0 0 10px; font-size:13px; color:var(--text)}
+.footer__col a{display:block; padding:6px 0; font-size:12px; color:var(--text-muted)}
+.footer__col a:hover{color:var(--text); text-decoration:underline}
+.legal{margin-top:22px; font-size:12px; color:var(--text-muted); line-height:1.45}
+.legal p{margin:0 0 10px}
+
+/* Mobile footer accordion */
+.footer__acc{
+  display:none;
+  border-top:1px solid var(--border);
+}
+.acc__item{border-bottom:1px solid var(--border)}
+.acc__button{
+  width:100%;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  padding:14px 0;
+  background:transparent;
+  border:0;
+  cursor:pointer;
+  font-size:13px;
+  color:var(--text);
+}
+.acc__panel{display:none; padding-bottom:12px}
+.acc__panel a{display:block; padding:6px 0; font-size:12px; color:var(--text-muted)}
+.acc__panel a:hover{color:var(--text); text-decoration:underline}
+.acc__item.is-open .acc__panel{display:block}
+.acc__chev{transition: transform .16s ease}
+.acc__item.is-open .acc__chev{transform: rotate(180deg)}
+
+/* Responsive */
+@media (max-width: 980px){
+  h1{font-size:44px}
+  h2{font-size:34px}
+  .hero__grid{grid-template-columns:1fr}
+  .footer__col{grid-column: span 6}
+  .panel{grid-column: span 12}
+  .carousel__nav--prev{left:4px}
+  .carousel__nav--next{right:4px}
+}
+
+@media (max-width: 720px){
+  section{padding:44px 0}
+  .navlinks{gap:8px}
+  .navlinks a{padding:8px}
+  h1{font-size:36px}
+  h2{font-size:28px}
+  .tile--half,.tile--third{grid-column: span 12}
+  .footer__cols{display:none}
+  .footer__acc{display:block}
+}
+
*** End Patch
PATCH

